import { defineComponent, computed, h, ref, type PropType } from 'vue';
import { getSwitchState, switchStyleKeys } from '../lib/core';
import type { SwitchSize } from '../lib/core';
import styles from './switch.module.scss';

export const Switch = defineComponent({
	name: 'Switch',
	props: {
		modelValue: { type: Boolean, default: undefined },
		defaultChecked: { type: Boolean, default: false },
		size: {
			type: String as PropType<SwitchSize>,
			default: 'default',
		},
		disabled: { type: Boolean, default: false },
	},
	emits: ['update:modelValue', 'change'],
	setup(props, { emit }) {
		const internalChecked = ref(props.defaultChecked);
		const isChecked = computed(() => (props.modelValue !== undefined ? props.modelValue : internalChecked.value));
		const state = computed(() => getSwitchState(isChecked.value));

		function handleClick() {
			const next = !isChecked.value;
			if (props.modelValue === undefined) {
				internalChecked.value = next;
			}
			emit('update:modelValue', next);
			emit('change', next);
		}

		return () =>
			h(
				'button',
				{
					type: 'button',
					role: 'switch',
					'aria-checked': isChecked.value ? 'true' : 'false',
					'data-state': state.value,
					'data-size': props.size,
					disabled: props.disabled,
					class: styles[switchStyleKeys.root],
					onClick: handleClick,
				},
				[h('span', { class: styles[switchStyleKeys.thumb] })],
			);
	},
});

export default Switch;

@use '../../../styles/variables/colors' as *;

.root {
	display: inline-flex;
	flex-shrink: 0;
	align-items: center;
	border-radius: var(--tile-switch-radius, #{$radius-full});
	border: var(--tile-switch-border-width, 1px) solid transparent;
	box-shadow: var(--tile-switch-shadow, #{$shadow-sm});
	transition: background-color $transition-fast;
	outline: none;

	&:focus-visible {
		border-color: $ring;
	}

	&:disabled {
		cursor: not-allowed;
		opacity: 0.5;
	}

	&[data-size='default'] {
		width: var(--tile-switch-width, 2rem);
		height: var(--tile-switch-height, 1.15rem);
	}

	&[data-size='sm'] {
		width: var(--tile-switch-sm-width, 1.5rem);
		height: var(--tile-switch-sm-height, 0.875rem);
	}

	&[data-state='checked'] {
		background-color: var(--tile-switch-checked-background, #{$primary});
		color: $primary-foreground;
		box-shadow: var(--tile-switch-checked-shadow, #{$shadow-sm});
	}

	&[data-state='unchecked'] {
		background-color: var(--tile-switch-background, #{$input});
		color: $foreground;
	}

	&:focus-visible {
		box-shadow: var(--tile-switch-focus-shadow, 0 0 0 1px #{$ring}, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
		outline: var(--tile-switch-focus-outline, none);
		outline-offset: var(--tile-switch-focus-offset, 0px);
	}
}

.thumb {
	pointer-events: none;
	display: block;
	border-radius: var(--tile-switch-radius, #{$radius-full});
	background-color: var(--tile-switch-thumb-background, #{$background});
	box-shadow: var(--tile-switch-thumb-shadow, none);
	transition: transform $transition-normal;

	[data-size='default'] & {
		width: var(--tile-switch-thumb-size, 1rem);
		height: var(--tile-switch-thumb-size, 1rem);
	}

	[data-size='sm'] & {
		width: var(--tile-switch-sm-thumb-size, 0.75rem);
		height: var(--tile-switch-sm-thumb-size, 0.75rem);
	}

	[data-state='checked'] & {
		transform: translateX(var(--tile-switch-thumb-travel, calc(100% - 2px)));
		background-color: var(--tile-switch-checked-thumb-background, #{$background});
	}

	[data-state='unchecked'] & {
		transform: translateX(0);
	}
}

// Optional corner styling falls back to round corners in unsupported browsers.
@supports (corner-shape: squircle) {
	.root,
	.thumb {
		corner-shape: var(--tile-switch-corner-shape, round);
		border-radius: var(--tile-switch-squircle-radius, #{$radius-full});
	}
}
